action.mutation:
mutation CreateIntegrationModel($payload: [IntegrationModelCreatePayloadInput!]!) {
  mutation: createIntegrationModel(payload: $payload) { 
    id
    name
  }
}

mutation UpdateIntegrationModel($payload: [IntegrationModelUpdatePayloadInput!]!) {
  mutation: updateIntegrationModel(payload: $payload) { 
    id
    name
  }
}

mutation DeleteIntegrationModel($payload: [IntegrationModelDeletePayloadInput!]!) {
  mutation: deleteIntegrationModel(payload: $payload) { 
    id
    name
  }
}
